import js from '@eslint/js'
import { globalIgnores } from 'eslint/config'
import tseslint from 'typescript-eslint'

export default tseslint.config(
  // src/gen is protoc-gen-es output (ADR 0021), regenerated by `buf generate`
  // and never hand-edited; its own `/* eslint-disable */` header exists for
  // humans reading it in an editor without this config, not for eslint here.
  globalIgnores(['dist', 'src/gen', 'public']),
  js.configs.recommended,
  tseslint.configs.recommended,
  {
    // src/lib/radix (preactcn's vendored Radix-for-Preact interop shim) and
    // src/components/ui (the preactcn components themselves) are both
    // written by `npx shadcn add`, never by hand - generic ref-forwarding,
    // a documented prop-spread cast, and an internal collection type all
    // need rules this project would otherwise enforce, and none of it is
    // ours to restyle.
    files: ['src/lib/radix/**/*.{ts,tsx}', 'src/components/ui/**/*.{ts,tsx}'],
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-empty-object-type': 'off',
      '@typescript-eslint/no-unused-vars': 'off',
    },
  },
  {
    // The base-ui shim behind @preactcn/combobox is written by `npx shadcn add` too, and it carries the same kind
    // of generic code as the radix shim above (the namespace of its component types, untyped ref and prop plumbing).
    files: ['src/lib/shims/base-ui-react.tsx', 'src/lib/shims/internal/base-ui-*.{ts,tsx}', 'src/lib/shims/internal/shadcn-react-use-render.ts'],
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-empty-object-type': 'off',
      '@typescript-eslint/no-namespace': 'off',
      '@typescript-eslint/no-unused-vars': 'off',
    },
  },
  {
    // preactcn components merge `className` with their own classes; `class`
    // would replace the whole list (Preact spreads it last) and break layout.
    files: ['src/**/*.tsx'],
    ignores: ['src/components/ui/**'],
    rules: {
      'no-restricted-syntax': [
        'error',
        {
          selector: "JSXOpeningElement[name.name=/^[A-Z]/] > JSXAttribute[name.name='class']",
          message: 'Use className on components; class replaces their own classes.',
        },
      ],
    },
  },
)
